INSERT INTO subtopics (id, topic_id, title, description, sort_order, skill_id, outcome_code) VALUES
  ('51000000-0000-0000-0000-000000030101', '41000000-0000-0000-0000-000000000301', 'Place value to tens of thousands', 'Reads, writes and partitions numbers up to tens of thousands.', 1, 'ma2-place-value', 'MA2-RN-01'),
  ('51000000-0000-0000-0000-000000030102', '41000000-0000-0000-0000-000000000301', 'Tenths and hundredths', 'Reads, writes and compares decimals with tenths and hundredths.', 2, NULL, 'MA2-RN-02'),
  ('51000000-0000-0000-0000-000000030201', '41000000-0000-0000-0000-000000000302', 'Adding and subtracting', 'Adds and subtracts 2- to 4-digit numbers using written and mental strategies.', 1, 'ma2-add-sub', 'MA2-AR-01'),
  ('51000000-0000-0000-0000-000000030202', '41000000-0000-0000-0000-000000000302', 'Missing numbers in + and −', 'Finds the missing number in addition and subtraction number sentences.', 2, 'ma2-missing-addend', 'MA2-AR-02'),
  ('51000000-0000-0000-0000-000000030301', '41000000-0000-0000-0000-000000000303', 'Times tables to 10 × 10', 'Recalls multiplication facts up to 10 × 10.', 1, 'ma2-times-tables', 'MA2-MR-01'),
  ('51000000-0000-0000-0000-000000030302', '41000000-0000-0000-0000-000000000303', 'Missing numbers in × and ÷', 'Finds the missing number in multiplication and division number sentences.', 2, NULL, 'MA2-MR-02'),
  ('51000000-0000-0000-0000-000000030501', '41000000-0000-0000-0000-000000000305', 'Halves, quarters and eighths', 'Names, compares and finds fractions of shapes, collections and number lines.', 1, NULL, 'MA2-PF-01'),
  ('51000000-0000-0000-0000-000000030401', '41000000-0000-0000-0000-000000000304', 'Telling the time', 'Reads analog and digital times and works out how long things take.', 1, NULL, 'MA2-NSM-02'),
  ('51000000-0000-0000-0000-000000030402', '41000000-0000-0000-0000-000000000304', 'Length', 'Measures and converts lengths in metres, centimetres and millimetres.', 2, NULL, 'MA2-GM-02'),
  ('51000000-0000-0000-0000-000000030601', '41000000-0000-0000-0000-000000000306', 'Tables and graphs', 'Reads and compares data in tables, dot plots, picture graphs and column graphs.', 1, NULL, 'MA2-DATA-02'),
  ('51000000-0000-0000-0000-000000030602', '41000000-0000-0000-0000-000000000306', 'Chance', 'Describes how likely events are and compares chances.', 2, NULL, 'MA2-CHAN-01'),
  ('51000000-0000-0000-0000-000000040101', '41000000-0000-0000-0000-000000000401', 'Division facts', 'Uses multiplication facts to divide.', 1, 'ma2-division-facts', 'MA2-MR-01'),
  ('51000000-0000-0000-0000-000000040102', '41000000-0000-0000-0000-000000000401', 'Missing numbers in × and ÷', 'Finds the missing number in multiplication and division number sentences.', 2, 'ma2-missing-factor', 'MA2-MR-02'),
  ('51000000-0000-0000-0000-000000040201', '41000000-0000-0000-0000-000000000402', 'Equivalent fractions', 'Recognises equivalent fractions with denominators 2, 4, 8, 3, 6, 5 and 10.', 1, 'ma2-equivalent-fractions', 'MA2-PF-01'),
  ('51000000-0000-0000-0000-000000040202', '41000000-0000-0000-0000-000000000402', 'Tenths and hundredths', 'Writes and compares decimals to two decimal places.', 2, 'ma2-decimals', 'MA2-RN-02'),
  ('51000000-0000-0000-0000-000000040301', '41000000-0000-0000-0000-000000000403', '2D shapes', 'Names 2D shapes and describes them by their sides and angles.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000050101', '41000000-0000-0000-0000-000000000501', 'Large numbers and rounding', 'Works with numbers into the millions and rounds to a given place.', 1, 'ma3-large-numbers', 'MA3-RN-01'),
  ('51000000-0000-0000-0000-000000050201', '41000000-0000-0000-0000-000000000502', 'Multiplying larger numbers', 'Multiplies 2- and 3-digit numbers by 1- and 2-digit numbers.', 1, 'ma3-multiply', 'MA3-MR-01'),
  ('51000000-0000-0000-0000-000000050202', '41000000-0000-0000-0000-000000000502', 'Dividing with remainders', 'Divides 3-digit numbers by 1-digit numbers and records remainders.', 2, 'ma3-divide-remainders', 'MA3-MR-01'),
  ('51000000-0000-0000-0000-000000050301', '41000000-0000-0000-0000-000000000503', 'Decimals to thousandths', 'Compares and orders decimals to three decimal places.', 1, 'ma3-decimals', 'MA3-RN-02'),
  ('51000000-0000-0000-0000-000000050302', '41000000-0000-0000-0000-000000000503', 'Adding and subtracting decimals', 'Adds and subtracts decimals with up to two decimal places.', 2, 'ma3-add-sub-decimals', 'MA3-AR-01'),
  ('51000000-0000-0000-0000-000000050303', '41000000-0000-0000-0000-000000000503', 'Comparing and ordering decimals', 'Compares and orders decimals using place value.', 3, NULL, NULL),
  ('51000000-0000-0000-0000-000000060101', '41000000-0000-0000-0000-000000000601', 'Order of operations', 'Uses brackets, ×, ÷, + and − in the correct order.', 1, 'ma3-order-of-operations', 'MA3-MR-02'),
  ('51000000-0000-0000-0000-000000060201', '41000000-0000-0000-0000-000000000602', 'Adding and subtracting fractions', 'Adds and subtracts fractions with the same or related denominators.', 1, 'ma3-add-fractions', 'MA3-RQF-01'),
  ('51000000-0000-0000-0000-000000060202', '41000000-0000-0000-0000-000000000602', 'Fraction of a quantity', 'Finds a fraction of a whole number, such as 3/4 of 20.', 2, 'ma3-fraction-of-quantity', 'MA3-RQF-02'),
  ('51000000-0000-0000-0000-000000060203', '41000000-0000-0000-0000-000000000602', 'Percentages of amounts', 'Finds 10%, 25%, 50% and 75% of amounts, including money.', 3, 'ma3-percentages', 'MA3-RQF-02'),
  ('51000000-0000-0000-0000-000000060301', '41000000-0000-0000-0000-000000000603', 'Angles', 'Names types of angles and uses angle facts to find unknown angles.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000031101', '41000000-0000-0000-0000-000000000311', 'Spelling patterns', 'Spells words with common vowel teams, suffixes and silent letters.', 1, 'en2-spelling', 'EN2-SPELL-01'),
  ('51000000-0000-0000-0000-000000031201', '41000000-0000-0000-0000-000000000312', 'Word meanings', 'Works out what words mean, including synonyms and antonyms.', 1, 'en2-vocabulary', 'EN2-VOCAB-01'),
  ('51000000-0000-0000-0000-000000031301', '41000000-0000-0000-0000-000000000313', 'Reading for meaning', 'Finds information, makes inferences and explains word choices in a text.', 1, 'en2-comprehension', 'EN2-RECOM-01'),
  ('51000000-0000-0000-0000-000000031401', '41000000-0000-0000-0000-000000000314', 'Capital letters and full stops', 'Uses capital letters and end punctuation correctly.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000041101', '41000000-0000-0000-0000-000000000411', 'Writing a story', 'Plans and writes a short story with a clear problem and resolution.', 1, 'en2-imaginative', 'EN2-CWT-01'),
  ('51000000-0000-0000-0000-000000041102', '41000000-0000-0000-0000-000000000411', 'Writing to persuade', 'States an opinion and backs it with reasons in paragraphs.', 2, 'en2-persuasive', 'EN2-CWT-03'),
  ('51000000-0000-0000-0000-000000041201', '41000000-0000-0000-0000-000000000412', 'Nouns, verbs and adjectives', 'Identifies nouns, verbs and adjectives in sentences.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000041202', '41000000-0000-0000-0000-000000000412', 'Building sentences', 'Puts words and events in a sensible order.', 2, NULL, NULL),
  ('51000000-0000-0000-0000-000000051101', '41000000-0000-0000-0000-000000000511', 'Spelling with prefixes and suffixes', 'Uses base words, prefixes, suffixes and word origins to spell.', 1, 'en3-spelling', 'EN3-SPELL-01'),
  ('51000000-0000-0000-0000-000000051201', '41000000-0000-0000-0000-000000000512', 'Precise vocabulary', 'Chooses precise words and understands figurative language.', 1, 'en3-vocabulary', 'EN3-VOCAB-01'),
  ('51000000-0000-0000-0000-000000051301', '41000000-0000-0000-0000-000000000513', 'Inference and author''s purpose', 'Infers meaning, identifies the author''s purpose and evaluates texts.', 1, 'en3-comprehension', 'EN3-RECOM-01'),
  ('51000000-0000-0000-0000-000000051401', '41000000-0000-0000-0000-000000000514', 'Apostrophes', 'Uses apostrophes for contractions and to show belonging.', 1, NULL, NULL),
  ('51000000-0000-0000-0000-000000061101', '41000000-0000-0000-0000-000000000611', 'Writing to inform', 'Writes an organised informative text with topic sentences and facts.', 1, 'en3-informative', 'EN3-CWT-02'),
  ('51000000-0000-0000-0000-000000061102', '41000000-0000-0000-0000-000000000611', 'Persuasive essays', 'Writes a persuasive text with an introduction, arguments, evidence and conclusion.', 2, 'en3-persuasive', 'EN3-CWT-03'),
  ('51000000-0000-0000-0000-000000061201', '41000000-0000-0000-0000-000000000612', 'Figurative language', 'Recognises similes, metaphors, personification and onomatopoeia.', 1, NULL, NULL)
INSERT INTO questions (id, subtopic_id, difficulty, points, question_text, question_type, answer_options, correct_answer, explanation, picture, created_by) VALUES
  ('61000000-0000-0000-0000-000003010101', '51000000-0000-0000-0000-000000030101', 'very_easy', 1, 'What is the value of the 4 in 47?', 'multiple_choice', '[{"id":"a","text":"4"},{"id":"b","text":"40"},{"id":"c","text":"400"},{"id":"d","text":"47"}]'::jsonb, '"b"'::jsonb, 'The 4 is in the tens place, so it is worth 4 tens, or 40.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010102', '51000000-0000-0000-0000-000000030101', 'very_easy', 1, 'What number do these blocks show?', 'short_answer', NULL, '"35"'::jsonb, 'There are 3 tens and 5 ones. 3 tens is 30, and 30 + 5 = 35.', '{"kind":"blocks","hundreds":0,"tens":3,"ones":5}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010103', '51000000-0000-0000-0000-000000030101', 'very_easy', 1, 'In 62, the 6 is in the tens place.', 'true_false', NULL, '"true"'::jsonb, '62 is 6 tens and 2 ones, so the 6 is in the tens place.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010104', '51000000-0000-0000-0000-000000030101', 'easy', 1, 'Which number do these blocks show?', 'multiple_choice', '[{"id":"a","text":"235"},{"id":"b","text":"253"},{"id":"c","text":"2053"},{"id":"d","text":"325"}]'::jsonb, '"b"'::jsonb, '2 hundreds, 5 tens and 3 ones is 253.', '{"kind":"blocks","hundreds":2,"tens":5,"ones":3}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010105', '51000000-0000-0000-0000-000000030101', 'easy', 1, 'What number is 1 more than 399?', 'short_answer', NULL, '"400"'::jsonb, 'One more than 399 fills the ones and the tens, so it goes up to 400.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010106', '51000000-0000-0000-0000-000000030101', 'easy', 1, 'Put these numbers in order from smallest to largest.', 'ordering', '[{"id":"a","text":"189"},{"id":"b","text":"198"},{"id":"c","text":"819"},{"id":"d","text":"891"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Compare the hundreds first, then the tens: 189, 198, 819, 891.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010107', '51000000-0000-0000-0000-000000030101', 'medium', 1, '4628 = 4000 + 600 + ___ + 8', 'fill_blank', NULL, '"20"'::jsonb, 'The 2 in 4628 is in the tens place, so it is worth 20.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010108', '51000000-0000-0000-0000-000000030101', 'medium', 1, 'What is the value of the 7 in 3742?', 'multiple_choice', '[{"id":"a","text":"7"},{"id":"b","text":"70"},{"id":"c","text":"700"},{"id":"d","text":"7000"}]'::jsonb, '"c"'::jsonb, 'The 7 is in the hundreds place, so it is worth 700.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010109', '51000000-0000-0000-0000-000000030101', 'medium', 1, 'What number is 100 more than 2950?', 'short_answer', NULL, '"3050"'::jsonb, 'Adding 100 adds 1 to the hundreds: 9 hundreds becomes 10 hundreds, so 2950 becomes 3050.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010110', '51000000-0000-0000-0000-000000030101', 'hard', 1, 'Which number is the largest?', 'multiple_choice', '[{"id":"a","text":"4099"},{"id":"b","text":"4909"},{"id":"c","text":"4990"},{"id":"d","text":"4900"}]'::jsonb, '"c"'::jsonb, 'All have 4 thousands. 4990 has 9 hundreds and 9 tens, more than the others.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010111', '51000000-0000-0000-0000-000000030101', 'hard', 1, 'Round 6483 to the nearest hundred.', 'short_answer', NULL, '"6500"'::jsonb, '6483 is between 6400 and 6500. The tens digit is 8, so it rounds up to 6500.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010112', '51000000-0000-0000-0000-000000030101', 'hard', 1, 'Which of these are equal to 5306? Choose all that are right.', 'multi_select', '[{"id":"a","text":"5 thousands, 3 hundreds and 6 ones"},{"id":"b","text":"53 hundreds and 6 ones"},{"id":"c","text":"5000 + 30 + 6"},{"id":"d","text":"530 tens and 6 ones"}]'::jsonb, '["a","b","d"]'::jsonb, '53 hundreds is 5300 and 530 tens is also 5300, so both make 5306. But 5000 + 30 + 6 is only 5036.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010113', '51000000-0000-0000-0000-000000030101', 'very_hard', 1, 'What is the largest 4-digit number you can make using the digits 3, 8, 1 and 6 once each?', 'short_answer', NULL, '"8631"'::jsonb, 'Put the biggest digit in the thousands place, then the next biggest, and so on: 8631.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010114', '51000000-0000-0000-0000-000000030101', 'very_hard', 1, 'What number is 10 less than 10 000?', 'short_answer', NULL, '"9990"'::jsonb, '10 000 − 10 = 9990.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010115', '51000000-0000-0000-0000-000000030101', 'very_hard', 1, 'How many hundreds are there in 4500?', 'short_answer', NULL, '"45"'::jsonb, '4500 is 4000 + 500. 4000 is 40 hundreds and 500 is 5 hundreds, so 45 hundreds.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010201', '51000000-0000-0000-0000-000000030102', 'very_easy', 1, 'A pizza is cut into 10 equal slices. What fraction of the pizza is one slice?', 'multiple_choice', '[{"id":"a","text":"one half"},{"id":"b","text":"one tenth"},{"id":"c","text":"one hundredth"},{"id":"d","text":"ten"}]'::jsonb, '"b"'::jsonb, '10 equal parts are tenths, so one slice is one tenth.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010202', '51000000-0000-0000-0000-000000030102', 'very_easy', 1, '0.5 is the same as five tenths.', 'true_false', NULL, '"true"'::jsonb, 'The first place after the decimal point is tenths, so 0.5 is 5 tenths.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010203', '51000000-0000-0000-0000-000000030102', 'very_easy', 1, 'Which decimal shows three tenths?', 'multiple_choice', '[{"id":"a","text":"3.0"},{"id":"b","text":"0.3"},{"id":"c","text":"0.03"},{"id":"d","text":"30"}]'::jsonb, '"b"'::jsonb, 'Three tenths is written 0.3: no ones, and 3 in the tenths place.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010204', '51000000-0000-0000-0000-000000030102', 'easy', 1, 'Write seven tenths as a decimal.', 'short_answer', NULL, '["0.7",".7"]'::jsonb, 'Seven tenths has 7 in the tenths place: 0.7.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010205', '51000000-0000-0000-0000-000000030102', 'easy', 1, 'Which is bigger, 0.6 or 0.4?', 'multiple_choice', '[{"id":"a","text":"0.6"},{"id":"b","text":"0.4"},{"id":"c","text":"They are the same"}]'::jsonb, '"a"'::jsonb, '6 tenths is more than 4 tenths.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010206', '51000000-0000-0000-0000-000000030102', 'easy', 1, '1 whole = ___ tenths', 'fill_blank', NULL, '"10"'::jsonb, 'A whole cut into tenths has 10 parts.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010207', '51000000-0000-0000-0000-000000030102', 'medium', 1, 'Put these decimals in order from smallest to largest.', 'ordering', '[{"id":"a","text":"0.2"},{"id":"b","text":"0.5"},{"id":"c","text":"0.8"},{"id":"d","text":"1.1"}]'::jsonb, '["a","b","c","d"]'::jsonb, '0.2, 0.5 and 0.8 are less than 1, and 1.1 is more than 1.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010208', '51000000-0000-0000-0000-000000030102', 'medium', 1, '0.3 + 0.4 = ?', 'short_answer', NULL, '"0.7"'::jsonb, '3 tenths and 4 tenths make 7 tenths, which is 0.7.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010209', '51000000-0000-0000-0000-000000030102', 'medium', 1, 'Which decimal is 2 wholes and 5 tenths?', 'multiple_choice', '[{"id":"a","text":"2.5"},{"id":"b","text":"25"},{"id":"c","text":"0.25"},{"id":"d","text":"5.2"}]'::jsonb, '"a"'::jsonb, '2 wholes go before the decimal point and 5 tenths after it: 2.5.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010210', '51000000-0000-0000-0000-000000030102', 'hard', 1, 'What is the value of the 4 in 3.47?', 'multiple_choice', '[{"id":"a","text":"4 ones"},{"id":"b","text":"4 tenths"},{"id":"c","text":"4 hundredths"},{"id":"d","text":"40"}]'::jsonb, '"b"'::jsonb, 'The first digit after the decimal point is tenths, so the 4 is 4 tenths.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010211', '51000000-0000-0000-0000-000000030102', 'hard', 1, 'Write 25 hundredths as a decimal.', 'short_answer', NULL, '["0.25",".25"]'::jsonb, '25 hundredths is 2 tenths and 5 hundredths: 0.25.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010212', '51000000-0000-0000-0000-000000030102', 'hard', 1, '0.7 is greater than 0.65.', 'true_false', NULL, '"true"'::jsonb, '0.7 is the same as 0.70, and 70 hundredths is more than 65 hundredths.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010213', '51000000-0000-0000-0000-000000030102', 'very_hard', 1, 'Put these decimals in order from smallest to largest.', 'ordering', '[{"id":"a","text":"0.09"},{"id":"b","text":"0.3"},{"id":"c","text":"0.45"},{"id":"d","text":"0.5"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Write them all with two places: 0.09, 0.30, 0.45, 0.50.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010214', '51000000-0000-0000-0000-000000030102', 'very_hard', 1, '1 − 0.4 = ?', 'short_answer', NULL, '"0.6"'::jsonb, '1 whole is 10 tenths. 10 tenths take away 4 tenths is 6 tenths, or 0.6.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003010215', '51000000-0000-0000-0000-000000030102', 'very_hard', 1, 'Which of these are equal to one half? Choose all that are right.', 'multi_select', '[{"id":"a","text":"0.5"},{"id":"b","text":"0.50"},{"id":"c","text":"5 tenths"},{"id":"d","text":"0.05"}]'::jsonb, '["a","b","c"]'::jsonb, '0.5, 0.50 and 5 tenths are all one half. 0.05 is only 5 hundredths.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020101', '51000000-0000-0000-0000-000000030201', 'very_easy', 1, '6 + 7 = ?', 'short_answer', NULL, '"13"'::jsonb, 'Make a ten: 6 + 4 = 10, then 3 more is 13.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020102', '51000000-0000-0000-0000-000000030201', 'very_easy', 1, '15 − 9 = ?', 'short_answer', NULL, '"6"'::jsonb, 'Count up from 9: 9 + 1 = 10, then 5 more makes 15. That is 6 altogether.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020103', '51000000-0000-0000-0000-000000030201', 'very_easy', 1, '8 + 5 is the same as 5 + 8.', 'true_false', NULL, '"true"'::jsonb, 'You can add numbers in any order and get the same total, 13.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020104', '51000000-0000-0000-0000-000000030201', 'easy', 1, '34 + 25 = ?', 'short_answer', NULL, '"59"'::jsonb, 'Add the tens: 30 + 20 = 50. Add the ones: 4 + 5 = 9. 50 + 9 = 59.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020105', '51000000-0000-0000-0000-000000030201', 'easy', 1, '78 − 46 = ?', 'short_answer', NULL, '"32"'::jsonb, 'Take away the tens: 70 − 40 = 30. Take away the ones: 8 − 6 = 2. 30 + 2 = 32.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020106', '51000000-0000-0000-0000-000000030201', 'easy', 1, 'Which is the same as 40 + 30?', 'multiple_choice', '[{"id":"a","text":"7"},{"id":"b","text":"70"},{"id":"c","text":"700"},{"id":"d","text":"43"}]'::jsonb, '"b"'::jsonb, '4 tens and 3 tens make 7 tens, which is 70.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020107', '51000000-0000-0000-0000-000000030201', 'medium', 1, '347 + 285 = ?', 'short_answer', NULL, '"632"'::jsonb, 'Hundreds: 300 + 200 = 500. Tens: 40 + 80 = 120. Ones: 7 + 5 = 12. 500 + 120 + 12 = 632.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020108', '51000000-0000-0000-0000-000000030201', 'medium', 1, '500 − 168 = ?', 'short_answer', NULL, '"332"'::jsonb, 'Count up from 168: 2 to 170, 30 to 200, then 300 to 500. 2 + 30 + 300 = 332.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020109', '51000000-0000-0000-0000-000000030201', 'medium', 1, 'Mia had 125 stickers and gave away 48. How many are left?', 'multiple_choice', '[{"id":"a","text":"77"},{"id":"b","text":"87"},{"id":"c","text":"173"},{"id":"d","text":"83"}]'::jsonb, '"a"'::jsonb, '125 − 48: take away 50 to get 75, then add back 2, which is 77.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020110', '51000000-0000-0000-0000-000000030201', 'hard', 1, '1250 + 2875 = ?', 'short_answer', NULL, '"4125"'::jsonb, '1000 + 2000 = 3000, 250 + 875 = 1125, and 3000 + 1125 = 4125.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020111', '51000000-0000-0000-0000-000000030201', 'hard', 1, 'A school has 406 students. 179 are girls. How many are boys?', 'short_answer', NULL, '"227"'::jsonb, '406 − 179: count up from 179. 21 to 200, then 206 to 406. 21 + 206 = 227.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020112', '51000000-0000-0000-0000-000000030201', 'hard', 1, 'Which is the best estimate of 298 + 403?', 'multiple_choice', '[{"id":"a","text":"500"},{"id":"b","text":"600"},{"id":"c","text":"700"},{"id":"d","text":"800"}]'::jsonb, '"c"'::jsonb, '298 is about 300 and 403 is about 400, so the total is about 700.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020113', '51000000-0000-0000-0000-000000030201', 'very_hard', 1, '3004 − 1568 = ?', 'short_answer', NULL, '"1436"'::jsonb, 'Count up from 1568: 32 to 1600, 400 to 2000, then 1004 to 3004. 32 + 400 + 1004 = 1436.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020114', '51000000-0000-0000-0000-000000030201', 'very_hard', 1, 'A book has 312 pages. Leo read 145 pages on Monday and 98 pages on Tuesday. How many pages are left?', 'short_answer', NULL, '"69"'::jsonb, 'Leo read 145 + 98 = 243 pages. 312 − 243 = 69 pages are left.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020115', '51000000-0000-0000-0000-000000030201', 'very_hard', 1, 'Which of these make exactly 1000? Choose all that are right.', 'multi_select', '[{"id":"a","text":"625 + 375"},{"id":"b","text":"1400 − 400"},{"id":"c","text":"480 + 520"},{"id":"d","text":"2000 − 1100"}]'::jsonb, '["a","b","c"]'::jsonb, '625 + 375, 1400 − 400 and 480 + 520 all make 1000. 2000 − 1100 is 900.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020201', '51000000-0000-0000-0000-000000030202', 'very_easy', 1, '4 + ___ = 10', 'fill_blank', NULL, '"6"'::jsonb, '4 and 6 make 10.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020202', '51000000-0000-0000-0000-000000030202', 'very_easy', 1, '___ + 3 = 8', 'fill_blank', NULL, '"5"'::jsonb, 'Count back 3 from 8 to get 5. Check: 5 + 3 = 8.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020203', '51000000-0000-0000-0000-000000030202', 'very_easy', 1, 'If 7 + 3 = 10, then 10 − 3 = 7.', 'true_false', NULL, '"true"'::jsonb, 'Adding and subtracting undo each other, so 10 − 3 gets back to 7.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020204', '51000000-0000-0000-0000-000000030202', 'easy', 1, '15 − ___ = 9', 'fill_blank', NULL, '"6"'::jsonb, '15 − 9 = 6, so the missing number is 6. Check: 15 − 6 = 9.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020205', '51000000-0000-0000-0000-000000030202', 'easy', 1, '20 + ___ = 50', 'fill_blank', NULL, '"30"'::jsonb, '2 tens and 3 tens make 5 tens, so the missing number is 30.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020206', '51000000-0000-0000-0000-000000030202', 'easy', 1, 'Which number makes 12 + ? = 20 true?', 'multiple_choice', '[{"id":"a","text":"6"},{"id":"b","text":"8"},{"id":"c","text":"32"},{"id":"d","text":"10"}]'::jsonb, '"b"'::jsonb, 'Count up from 12 to 20: that is 8.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020207', '51000000-0000-0000-0000-000000030202', 'medium', 1, '45 + ___ = 100', 'fill_blank', NULL, '"55"'::jsonb, '45 + 5 = 50, and 50 + 50 = 100. 5 + 50 = 55.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020208', '51000000-0000-0000-0000-000000030202', 'medium', 1, '___ − 25 = 40', 'fill_blank', NULL, '"65"'::jsonb, 'Add back the 25: 40 + 25 = 65. Check: 65 − 25 = 40.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020209', '51000000-0000-0000-0000-000000030202', 'medium', 1, 'I had some marbles. I won 14 more and now I have 31. Which number sentence matches?', 'multiple_choice', '[{"id":"a","text":"? + 14 = 31"},{"id":"b","text":"14 − ? = 31"},{"id":"c","text":"31 + 14 = ?"},{"id":"d","text":"? − 14 = 31"}]'::jsonb, '"a"'::jsonb, 'The unknown amount, plus the 14 won, makes 31: ? + 14 = 31.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020210', '51000000-0000-0000-0000-000000030202', 'hard', 1, '250 + ___ = 600', 'fill_blank', NULL, '"350"'::jsonb, 'Count up from 250: 50 to 300, then 300 to 600. 50 + 300 = 350.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020211', '51000000-0000-0000-0000-000000030202', 'hard', 1, '___ − 135 = 200', 'fill_blank', NULL, '"335"'::jsonb, 'Add back the 135: 200 + 135 = 335.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020212', '51000000-0000-0000-0000-000000030202', 'hard', 1, 'Ava needs 500 points to win. She has 362. How many more points does she need?', 'short_answer', NULL, '"138"'::jsonb, 'Count up from 362: 38 to 400, then 100 to 500. 38 + 100 = 138.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020213', '51000000-0000-0000-0000-000000030202', 'very_hard', 1, '1000 − ___ = 455', 'fill_blank', NULL, '"545"'::jsonb, '1000 − 455 = 545. Check: 455 + 545 = 1000.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020214', '51000000-0000-0000-0000-000000030202', 'very_hard', 1, '36 + ___ = 50 + 14', 'fill_blank', NULL, '"28"'::jsonb, '50 + 14 = 64, so 36 + ? = 64. 64 − 36 = 28.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003020215', '51000000-0000-0000-0000-000000030202', 'very_hard', 1, '47 + 28 = 45 + 30', 'true_false', NULL, '"true"'::jsonb, 'Both sides make 75. Taking 2 from 47 and giving it to 28 keeps the total the same.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030101', '51000000-0000-0000-0000-000000030301', 'very_easy', 1, '2 × 5 = ?', 'short_answer', NULL, '"10"'::jsonb, '2 groups of 5 is 5 + 5 = 10.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030102', '51000000-0000-0000-0000-000000030301', 'very_easy', 1, 'There are 3 rows with 4 dots in each row. How many dots altogether?', 'short_answer', NULL, '"12"'::jsonb, '3 rows of 4 is 4 + 4 + 4 = 12.', '{"kind":"array","rows":3,"columns":4}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030103', '51000000-0000-0000-0000-000000030301', 'very_easy', 1, '5 × 2 is the same as 2 × 5.', 'true_false', NULL, '"true"'::jsonb, 'You can multiply in any order. Both make 10.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030104', '51000000-0000-0000-0000-000000030301', 'easy', 1, '4 × 5 = ?', 'short_answer', NULL, '"20"'::jsonb, 'Count by fives 4 times: 5, 10, 15, 20.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030105', '51000000-0000-0000-0000-000000030301', 'easy', 1, '10 × 7 = ?', 'short_answer', NULL, '"70"'::jsonb, '10 groups of 7 is 70.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030106', '51000000-0000-0000-0000-000000030301', 'easy', 1, 'Which is the same as 3 + 3 + 3 + 3?', 'multiple_choice', '[{"id":"a","text":"3 × 3"},{"id":"b","text":"4 × 3"},{"id":"c","text":"3 + 4"},{"id":"d","text":"12 × 3"}]'::jsonb, '"b"'::jsonb, 'There are four 3s, so it is 4 × 3.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030107', '51000000-0000-0000-0000-000000030301', 'medium', 1, '6 × 4 = ?', 'short_answer', NULL, '"24"'::jsonb, 'Double 3 × 4 = 12 to get 24.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030108', '51000000-0000-0000-0000-000000030301', 'medium', 1, '20 ÷ 5 = ?', 'short_answer', NULL, '"4"'::jsonb, 'How many 5s make 20? 5, 10, 15, 20: four.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030109', '51000000-0000-0000-0000-000000030301', 'medium', 1, '18 apples are shared equally into 3 bags. How many apples go in each bag?', 'multiple_choice', '[{"id":"a","text":"5"},{"id":"b","text":"6"},{"id":"c","text":"7"},{"id":"d","text":"15"}]'::jsonb, '"b"'::jsonb, '18 ÷ 3 = 6, because 3 × 6 = 18.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030110', '51000000-0000-0000-0000-000000030301', 'hard', 1, '7 × 8 = ?', 'short_answer', NULL, '"56"'::jsonb, '7 × 8 = 56. Remember 5, 6, 7, 8: 56 = 7 × 8.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030111', '51000000-0000-0000-0000-000000030301', 'hard', 1, 'There are 9 rows of chairs with 6 chairs in each row. How many chairs are there?', 'short_answer', NULL, '"54"'::jsonb, '9 × 6 = 54.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030112', '51000000-0000-0000-0000-000000030301', 'hard', 1, 'Which of these make 24? Choose all that are right.', 'multi_select', '[{"id":"a","text":"3 × 8"},{"id":"b","text":"4 × 6"},{"id":"c","text":"5 × 5"},{"id":"d","text":"2 × 12"}]'::jsonb, '["a","b","d"]'::jsonb, '3 × 8, 4 × 6 and 2 × 12 all make 24. 5 × 5 is 25.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030113', '51000000-0000-0000-0000-000000030301', 'very_hard', 1, '63 ÷ 9 = ?', 'short_answer', NULL, '"7"'::jsonb, 'Think: 9 × what = 63? 9 × 7 = 63, so the answer is 7.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030114', '51000000-0000-0000-0000-000000030301', 'very_hard', 1, 'Tickets cost $8 each. How many dollars do 7 tickets cost?', 'short_answer', NULL, '["56","$56"]'::jsonb, '7 × 8 = 56, so 7 tickets cost $56.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030115', '51000000-0000-0000-0000-000000030301', 'very_hard', 1, 'A baker puts 6 cupcakes in each box. How many boxes are needed for 45 cupcakes?', 'short_answer', NULL, '"8"'::jsonb, '7 boxes hold 42 cupcakes, leaving 3 more. They need one more box, so 8 boxes.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030201', '51000000-0000-0000-0000-000000030302', 'very_easy', 1, '2 × ___ = 6', 'fill_blank', NULL, '"3"'::jsonb, '2 groups of 3 make 6.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030202', '51000000-0000-0000-0000-000000030302', 'very_easy', 1, '___ × 5 = 10', 'fill_blank', NULL, '"2"'::jsonb, 'Two 5s make 10.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030203', '51000000-0000-0000-0000-000000030302', 'very_easy', 1, 'If 3 × 4 = 12, then 12 ÷ 4 = 3.', 'true_false', NULL, '"true"'::jsonb, 'Multiplying and dividing undo each other.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030204', '51000000-0000-0000-0000-000000030302', 'easy', 1, '___ × 10 = 40', 'fill_blank', NULL, '"4"'::jsonb, '4 tens make 40.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030205', '51000000-0000-0000-0000-000000030302', 'easy', 1, '12 ÷ ___ = 6', 'fill_blank', NULL, '"2"'::jsonb, '12 shared into 2 equal groups gives 6 in each.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030206', '51000000-0000-0000-0000-000000030302', 'easy', 1, 'Which number makes 5 × ? = 25 true?', 'multiple_choice', '[{"id":"a","text":"4"},{"id":"b","text":"5"},{"id":"c","text":"20"},{"id":"d","text":"6"}]'::jsonb, '"b"'::jsonb, '5 × 5 = 25.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030207', '51000000-0000-0000-0000-000000030302', 'medium', 1, '4 × ___ = 28', 'fill_blank', NULL, '"7"'::jsonb, 'Count by fours to 28: 4, 8, 12, 16, 20, 24, 28. That is 7 fours.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030208', '51000000-0000-0000-0000-000000030302', 'medium', 1, '___ ÷ 3 = 6', 'fill_blank', NULL, '"18"'::jsonb, 'Undo the division: 6 × 3 = 18.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030209', '51000000-0000-0000-0000-000000030302', 'medium', 1, 'Some boxes hold 8 pens each. There are 32 pens. Which number sentence finds the number of boxes?', 'multiple_choice', '[{"id":"a","text":"? × 8 = 32"},{"id":"b","text":"32 × 8 = ?"},{"id":"c","text":"8 − ? = 32"},{"id":"d","text":"? + 8 = 32"}]'::jsonb, '"a"'::jsonb, 'Some number of boxes, times 8 pens in each, makes 32: ? × 8 = 32.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030210', '51000000-0000-0000-0000-000000030302', 'hard', 1, '___ × 9 = 72', 'fill_blank', NULL, '"8"'::jsonb, '8 × 9 = 72.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030211', '51000000-0000-0000-0000-000000030302', 'hard', 1, '60 ÷ ___ = 10', 'fill_blank', NULL, '"6"'::jsonb, '6 × 10 = 60, so 60 ÷ 6 = 10.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030212', '51000000-0000-0000-0000-000000030302', 'hard', 1, 'A number multiplied by 6 is 54. What is the number?', 'short_answer', NULL, '"9"'::jsonb, '? × 6 = 54. Since 9 × 6 = 54, the number is 9.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030213', '51000000-0000-0000-0000-000000030302', 'very_hard', 1, '3 × ___ = 2 × 12', 'fill_blank', NULL, '"8"'::jsonb, '2 × 12 = 24, so 3 × ? = 24, and 3 × 8 = 24.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030214', '51000000-0000-0000-0000-000000030302', 'very_hard', 1, '___ ÷ 7 = 4 + 3', 'fill_blank', NULL, '"49"'::jsonb, '4 + 3 = 7, so ? ÷ 7 = 7. Undo it: 7 × 7 = 49.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003030215', '51000000-0000-0000-0000-000000030302', 'very_hard', 1, '8 × 5 = 4 × 10', 'true_false', NULL, '"true"'::jsonb, 'Both make 40. Halving 8 and doubling 5 keeps the answer the same.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050101', '51000000-0000-0000-0000-000000030501', 'very_easy', 1, 'A cake is cut into 2 equal pieces. What is each piece called?', 'multiple_choice', '[{"id":"a","text":"a half"},{"id":"b","text":"a quarter"},{"id":"c","text":"a third"},{"id":"d","text":"a whole"}]'::jsonb, '"a"'::jsonb, '2 equal parts are halves.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050102', '51000000-0000-0000-0000-000000030501', 'very_easy', 1, 'One quarter of this circle is shaded.', 'true_false', NULL, '"true"'::jsonb, 'The circle is cut into 4 equal parts and 1 is shaded, so one quarter is shaded.', '{"kind":"fraction","shape":"circle","parts":4,"shaded":1}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050103', '51000000-0000-0000-0000-000000030501', 'very_easy', 1, 'How many quarters make a whole?', 'multiple_choice', '[{"id":"a","text":"2"},{"id":"b","text":"3"},{"id":"c","text":"4"},{"id":"d","text":"8"}]'::jsonb, '"c"'::jsonb, 'A whole cut into quarters has 4 equal parts.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050104', '51000000-0000-0000-0000-000000030501', 'easy', 1, 'What is half of 10?', 'short_answer', NULL, '"5"'::jsonb, '10 shared into 2 equal groups is 5 in each.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050105', '51000000-0000-0000-0000-000000030501', 'easy', 1, 'What fraction of the bar is shaded?', 'multiple_choice', '[{"id":"a","text":"1/4"},{"id":"b","text":"3/4"},{"id":"c","text":"3/1"},{"id":"d","text":"4/3"}]'::jsonb, '"b"'::jsonb, 'The bar is cut into 4 equal parts and 3 are shaded, so 3/4 is shaded.', '{"kind":"fraction","shape":"bar","parts":4,"shaded":3}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050106', '51000000-0000-0000-0000-000000030501', 'easy', 1, '1/2 is bigger than 1/4.', 'true_false', NULL, '"true"'::jsonb, 'Cutting a whole into 2 parts makes bigger parts than cutting it into 4.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050107', '51000000-0000-0000-0000-000000030501', 'medium', 1, 'What is one quarter of 12?', 'short_answer', NULL, '"3"'::jsonb, '12 shared into 4 equal groups is 3 in each.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050108', '51000000-0000-0000-0000-000000030501', 'medium', 1, 'Which fraction is equal to 1/2?', 'multiple_choice', '[{"id":"a","text":"2/4"},{"id":"b","text":"1/3"},{"id":"c","text":"3/4"},{"id":"d","text":"2/3"}]'::jsonb, '"a"'::jsonb, '2 quarters cover the same amount as 1 half.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050109', '51000000-0000-0000-0000-000000030501', 'medium', 1, 'Put these in order from smallest to largest.', 'ordering', '[{"id":"a","text":"1/8"},{"id":"b","text":"1/4"},{"id":"c","text":"1/2"},{"id":"d","text":"1"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'The more parts a whole is cut into, the smaller each part: 1/8, 1/4, 1/2, then 1 whole.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050110', '51000000-0000-0000-0000-000000030501', 'hard', 1, 'What is three quarters of 20?', 'short_answer', NULL, '"15"'::jsonb, 'One quarter of 20 is 5, so three quarters is 3 × 5 = 15.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050111', '51000000-0000-0000-0000-000000030501', 'hard', 1, 'What fraction is the dot on?', 'multiple_choice', '[{"id":"a","text":"1/4"},{"id":"b","text":"2/4"},{"id":"c","text":"3/4"},{"id":"d","text":"4/3"}]'::jsonb, '"c"'::jsonb, 'The line from 0 to 1 is split into 4 equal jumps, so each jump is 1/4. The dot is 3 jumps along: 3/4.', '{"kind":"number_line","from":0,"to":1,"jumps":4,"dotAt":3}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050112', '51000000-0000-0000-0000-000000030501', 'hard', 1, 'Which of these are equal to one whole? Choose all that are right.', 'multi_select', '[{"id":"a","text":"2/2"},{"id":"b","text":"4/4"},{"id":"c","text":"3/4"},{"id":"d","text":"5/5"}]'::jsonb, '["a","b","d"]'::jsonb, 'When the top and bottom numbers are the same, you have all the parts: one whole.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050113', '51000000-0000-0000-0000-000000030501', 'very_hard', 1, 'Tom ate 1/4 of a pizza and Kim ate 2/4 of it. What fraction of the pizza did they eat altogether?', 'short_answer', NULL, '["3/4","three quarters"]'::jsonb, '1 quarter and 2 quarters make 3 quarters, or 3/4.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050114', '51000000-0000-0000-0000-000000030501', 'very_hard', 1, '1/3 is bigger than 1/5.', 'true_false', NULL, '"true"'::jsonb, 'Thirds are bigger pieces than fifths, because the whole is shared into fewer parts.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003050115', '51000000-0000-0000-0000-000000030501', 'very_hard', 1, 'There are 16 apples. 3/8 of them are red. How many are red?', 'short_answer', NULL, '"6"'::jsonb, 'One eighth of 16 is 2, so three eighths is 3 × 2 = 6.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040102', '51000000-0000-0000-0000-000000030401', 'very_easy', 1, 'How many minutes are there in 1 hour?', 'short_answer', NULL, '"60"'::jsonb, 'There are 60 minutes in 1 hour.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040106', '51000000-0000-0000-0000-000000030401', 'very_easy', 1, 'There are ___ days in a week.', 'fill_blank', NULL, '["7","seven"]'::jsonb, 'A week has 7 days, Monday to Sunday.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040107', '51000000-0000-0000-0000-000000030401', 'very_easy', 1, 'There are 24 hours in a day.', 'true_false', NULL, '"true"'::jsonb, 'A day, from midnight to midnight, is 24 hours.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040101', '51000000-0000-0000-0000-000000030401', 'easy', 1, 'What time does the clock show?', 'multiple_choice', '[{"id":"a","text":"6:30"},{"id":"b","text":"3:30"},{"id":"c","text":"4:30"},{"id":"d","text":"3:06"}]'::jsonb, '"b"'::jsonb, 'When the minute hand points to the 6, it''s half past. The hour hand has passed the 3, so it''s half past 3, or 3:30.', '{"kind":"clock","hour":3,"minute":30}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040104', '51000000-0000-0000-0000-000000030401', 'easy', 1, 'This clock shows quarter past 7.', 'true_false', NULL, '"true"'::jsonb, 'The minute hand points to the 3, which is 15 minutes past. The hour hand is just past the 7, so it''s quarter past 7, or 7:15.', '{"kind":"clock","hour":7,"minute":15}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040108', '51000000-0000-0000-0000-000000030401', 'easy', 1, 'What time does the clock show?', 'multiple_choice', '[{"id":"a","text":"3:45"},{"id":"b","text":"4:15"},{"id":"c","text":"4:45"},{"id":"d","text":"9:20"}]'::jsonb, '"a"'::jsonb, 'The minute hand points to the 9, which is 45 minutes past, or quarter to the next hour. The hour hand is nearly at 4, so it''s 3:45.', '{"kind":"clock","hour":3,"minute":45}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040103', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'How many minutes are there from 2:15 to 2:45?', 'short_answer', NULL, '"30"'::jsonb, 'From 15 minutes past to 45 minutes past is 45 − 15 = 30 minutes.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040105', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'Put these morning times in order, from earliest to latest.', 'ordering', '[{"id":"a","text":"7:05"},{"id":"b","text":"7:50"},{"id":"c","text":"8:30"},{"id":"d","text":"9:45"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Compare the hours first, then the minutes: 7:05, 7:50, 8:30, 9:45.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040109', '51000000-0000-0000-0000-000000030401', 'medium', 1, 'How many minutes are there in 2 hours?', 'short_answer', NULL, '"120"'::jsonb, 'Each hour is 60 minutes, so 2 hours is 120 minutes.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040110', '51000000-0000-0000-0000-000000030401', 'hard', 1, 'A movie starts at 4:20 pm and lasts 1 hour 30 minutes. What time does it end?', 'short_answer', NULL, '["5:50","5:50 pm","5:50pm"]'::jsonb, '1 hour after 4:20 is 5:20, and 30 minutes more is 5:50 pm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040111', '51000000-0000-0000-0000-000000030401', 'hard', 1, 'What is 3:00 pm in 24-hour time?', 'multiple_choice', '[{"id":"a","text":"03:00"},{"id":"b","text":"13:00"},{"id":"c","text":"15:00"},{"id":"d","text":"12:00"}]'::jsonb, '"c"'::jsonb, 'Add 12 to afternoon hours: 3 + 12 = 15, so 15:00.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040112', '51000000-0000-0000-0000-000000030401', 'hard', 1, 'How many seconds are there in 2 minutes?', 'short_answer', NULL, '"120"'::jsonb, 'Each minute is 60 seconds, so 2 minutes is 120 seconds.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040113', '51000000-0000-0000-0000-000000030401', 'very_hard', 1, 'A bus leaves at 10:45 am and arrives at 1:15 pm. How many minutes long is the trip?', 'short_answer', NULL, '["150","150 minutes"]'::jsonb, '10:45 to 12:45 is 2 hours (120 minutes), and 12:45 to 1:15 is 30 minutes. 120 + 30 = 150 minutes.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040114', '51000000-0000-0000-0000-000000030401', 'very_hard', 1, 'What is 19:30 in 12-hour time?', 'multiple_choice', '[{"id":"a","text":"7:30 am"},{"id":"b","text":"7:30 pm"},{"id":"c","text":"9:30 pm"},{"id":"d","text":"1:30 pm"}]'::jsonb, '"b"'::jsonb, '19 − 12 = 7, and hours after 12 are pm, so 7:30 pm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040115', '51000000-0000-0000-0000-000000030401', 'very_hard', 1, 'School finishes at 3:10 pm. It takes Ali 25 minutes to walk home. What time does Ali get home?', 'short_answer', NULL, '["3:35","3:35 pm","3:35pm"]'::jsonb, '3:10 plus 25 minutes is 3:35 pm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040201', '51000000-0000-0000-0000-000000030402', 'very_easy', 1, 'Which unit would you use to measure a pencil?', 'multiple_choice', '[{"id":"a","text":"centimetres"},{"id":"b","text":"kilometres"},{"id":"c","text":"litres"},{"id":"d","text":"kilograms"}]'::jsonb, '"a"'::jsonb, 'A pencil is short, so centimetres are a good unit.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040202', '51000000-0000-0000-0000-000000030402', 'very_easy', 1, 'A metre is longer than a centimetre.', 'true_false', NULL, '"true"'::jsonb, '1 metre is 100 centimetres.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040203', '51000000-0000-0000-0000-000000030402', 'very_easy', 1, 'Which is the longest?', 'multiple_choice', '[{"id":"a","text":"1 cm"},{"id":"b","text":"1 m"},{"id":"c","text":"1 mm"}]'::jsonb, '"b"'::jsonb, '1 m is 100 cm, and 1 cm is 10 mm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040204', '51000000-0000-0000-0000-000000030402', 'easy', 1, '1 metre = ___ centimetres', 'fill_blank', NULL, '"100"'::jsonb, 'There are 100 centimetres in a metre.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040205', '51000000-0000-0000-0000-000000030402', 'easy', 1, 'Which unit would you use to measure the length of a classroom?', 'multiple_choice', '[{"id":"a","text":"millimetres"},{"id":"b","text":"metres"},{"id":"c","text":"grams"},{"id":"d","text":"hours"}]'::jsonb, '"b"'::jsonb, 'A classroom is a few metres long.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040206', '51000000-0000-0000-0000-000000030402', 'easy', 1, 'How many centimetres long is the pencil?', 'short_answer', NULL, '["7","7 cm"]'::jsonb, 'The pencil starts at 0 and ends at 7, so it is 7 cm long.', '{"kind":"ruler","cm":10,"length":7,"object":"pencil"}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040207', '51000000-0000-0000-0000-000000030402', 'medium', 1, '1 centimetre = ___ millimetres', 'fill_blank', NULL, '"10"'::jsonb, 'There are 10 millimetres in a centimetre.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040208', '51000000-0000-0000-0000-000000030402', 'medium', 1, 'How many centimetres are there in 3 metres?', 'short_answer', NULL, '"300"'::jsonb, 'Each metre is 100 cm, so 3 metres is 300 cm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040209', '51000000-0000-0000-0000-000000030402', 'medium', 1, 'Put these lengths in order from shortest to longest.', 'ordering', '[{"id":"a","text":"8 mm"},{"id":"b","text":"5 cm"},{"id":"c","text":"60 cm"},{"id":"d","text":"2 m"}]'::jsonb, '["a","b","c","d"]'::jsonb, '8 mm is less than 1 cm, then 5 cm, then 60 cm, and 2 m is 200 cm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040210', '51000000-0000-0000-0000-000000030402', 'hard', 1, 'What is the perimeter of this rectangle in centimetres?', 'short_answer', NULL, '["20","20 cm"]'::jsonb, 'Add all four sides: 6 + 4 + 6 + 4 = 20 cm.', '{"kind":"rectangle","width":6,"height":4,"top":"6 cm","side":"4 cm"}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040211', '51000000-0000-0000-0000-000000030402', 'hard', 1, '250 cm = 2 m and ___ cm', 'fill_blank', NULL, '"50"'::jsonb, '200 cm is 2 m, and 50 cm is left over.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040212', '51000000-0000-0000-0000-000000030402', 'hard', 1, 'Which length is the same as 1.5 m?', 'multiple_choice', '[{"id":"a","text":"15 cm"},{"id":"b","text":"150 cm"},{"id":"c","text":"105 cm"},{"id":"d","text":"1500 cm"}]'::jsonb, '"b"'::jsonb, '1 m is 100 cm and half a metre is 50 cm, so 1.5 m is 150 cm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040213', '51000000-0000-0000-0000-000000030402', 'very_hard', 1, 'Jo ran 3 laps of a 200 m track. How many metres did Jo run?', 'short_answer', NULL, '"600"'::jsonb, '3 × 200 = 600 m.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040214', '51000000-0000-0000-0000-000000030402', 'very_hard', 1, 'A square has a perimeter of 36 cm. How long is each side in centimetres?', 'short_answer', NULL, '"9"'::jsonb, 'A square has 4 equal sides, so 36 ÷ 4 = 9 cm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003040215', '51000000-0000-0000-0000-000000030402', 'very_hard', 1, 'How many millimetres are there in 4 cm 7 mm?', 'short_answer', NULL, '"47"'::jsonb, '4 cm is 40 mm, and 40 + 7 = 47 mm.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060101', '51000000-0000-0000-0000-000000030601', 'very_easy', 1, 'Look at the graph. Which fruit got the most votes?', 'multiple_choice', '[{"id":"a","text":"apple"},{"id":"b","text":"banana"},{"id":"c","text":"orange"}]'::jsonb, '"c"'::jsonb, 'Orange got 7 votes, more than 5 or 3.', '{"kind":"column_graph","title":"Favourite fruit","columns":[{"label":"apple","value":5},{"label":"banana","value":3},{"label":"orange","value":7}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060102', '51000000-0000-0000-0000-000000030601', 'very_easy', 1, 'Look at the graph. How many votes did banana get?', 'short_answer', NULL, '"3"'::jsonb, 'Read the banana row: 3 votes.', '{"kind":"column_graph","title":"Favourite fruit","columns":[{"label":"apple","value":5},{"label":"banana","value":3},{"label":"orange","value":7}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060103', '51000000-0000-0000-0000-000000030601', 'very_easy', 1, 'In a column graph, a taller column shows a bigger number.', 'true_false', NULL, '"true"'::jsonb, 'The height of each column shows how many.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060104', '51000000-0000-0000-0000-000000030601', 'easy', 1, 'Look at the graph. How many votes were there altogether?', 'short_answer', NULL, '"15"'::jsonb, '5 + 3 + 7 = 15.', '{"kind":"column_graph","title":"Favourite fruit","columns":[{"label":"apple","value":5},{"label":"banana","value":3},{"label":"orange","value":7}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060105', '51000000-0000-0000-0000-000000030601', 'easy', 1, 'Look at the graph. Which fruit got the fewest votes?', 'multiple_choice', '[{"id":"a","text":"apple"},{"id":"b","text":"banana"},{"id":"c","text":"orange"}]'::jsonb, '"b"'::jsonb, 'Banana got 3 votes, the smallest number.', '{"kind":"column_graph","title":"Favourite fruit","columns":[{"label":"apple","value":5},{"label":"banana","value":3},{"label":"orange","value":7}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060106', '51000000-0000-0000-0000-000000030601', 'easy', 1, 'Look at the graph. How many more votes did orange get than apple?', 'short_answer', NULL, '"2"'::jsonb, 'Orange got 7 and apple got 5, so 7 − 5 = 2 more votes.', '{"kind":"column_graph","title":"Favourite fruit","columns":[{"label":"apple","value":5},{"label":"banana","value":3},{"label":"orange","value":7}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060107', '51000000-0000-0000-0000-000000030601', 'medium', 1, 'The table shows pets owned by a class. How many more dogs than birds are there?', 'short_answer', NULL, '"6"'::jsonb, 'There are 8 dogs and 2 birds, so 8 − 2 = 6 more dogs.', '{"kind":"table","headings":["Pet","Number"],"rows":[["dogs",8],["cats",6],["fish",4],["birds",2]]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060108', '51000000-0000-0000-0000-000000030601', 'medium', 1, 'The table shows pets owned by a class. Which pairs of pets add up to 10?', 'multiple_choice', '[{"id":"a","text":"dogs and birds"},{"id":"b","text":"cats and fish"},{"id":"c","text":"both of these"},{"id":"d","text":"neither of these"}]'::jsonb, '"c"'::jsonb, 'Dogs and birds: 8 + 2 = 10. Cats and fish: 6 + 4 = 10. Both pairs make 10.', '{"kind":"table","headings":["Pet","Number"],"rows":[["dogs",8],["cats",6],["fish",4],["birds",2]]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060109', '51000000-0000-0000-0000-000000030601', 'medium', 1, 'The table shows pets owned by a class. Cats and fish together are more than dogs.', 'true_false', NULL, '"true"'::jsonb, '6 + 4 = 10, and 10 is more than 8.', '{"kind":"table","headings":["Pet","Number"],"rows":[["dogs",8],["cats",6],["fish",4],["birds",2]]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060110', '51000000-0000-0000-0000-000000030601', 'hard', 1, 'The dot plot shows test scores. Each dot is one student. Which score was most common?', 'multiple_choice', '[{"id":"a","text":"5"},{"id":"b","text":"6"},{"id":"c","text":"7"},{"id":"d","text":"8"}]'::jsonb, '"b"'::jsonb, 'The score with the most dots is 6, with 6 dots.', '{"kind":"dot_plot","title":"Test scores","columns":[{"label":"5","count":3},{"label":"6","count":6},{"label":"7","count":2},{"label":"8","count":0}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060111', '51000000-0000-0000-0000-000000030601', 'hard', 1, 'The dot plot shows test scores. Each dot is one student. How many students are shown?', 'short_answer', NULL, '"11"'::jsonb, 'Count all the dots: 3 + 6 + 2 = 11.', '{"kind":"dot_plot","title":"Test scores","columns":[{"label":"5","count":3},{"label":"6","count":6},{"label":"7","count":2},{"label":"8","count":0}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060112', '51000000-0000-0000-0000-000000030601', 'hard', 1, 'In a column graph, each square stands for 2 children. The ''walk to school'' column is 5 squares tall. How many children walk to school?', 'short_answer', NULL, '"10"'::jsonb, '5 squares × 2 children = 10 children.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060113', '51000000-0000-0000-0000-000000030601', 'very_hard', 1, 'The picture graph shows books read. How many more books did Jay read than Mia?', 'short_answer', NULL, '"15"'::jsonb, 'Jay has 3 more pictures than Mia, and 3 × 5 = 15 books.', '{"kind":"picture_graph","title":"Books read","thing":"books","each":5,"rows":[{"label":"Mia","count":4},{"label":"Jay","count":7},{"label":"Ava","count":5}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060114', '51000000-0000-0000-0000-000000030601', 'very_hard', 1, 'A survey asked 30 students. 12 chose soccer, 9 chose netball and the rest chose cricket. How many chose cricket?', 'multiple_choice', '[{"id":"a","text":"9"},{"id":"b","text":"21"},{"id":"c","text":"8"},{"id":"d","text":"12"}]'::jsonb, '"a"'::jsonb, '12 + 9 = 21 chose soccer or netball, so 30 − 21 = 9 chose cricket.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060115', '51000000-0000-0000-0000-000000030601', 'very_hard', 1, 'The graph shows rainy days. Which of these are true? Choose all that are right.', 'multi_select', '[{"id":"a","text":"Tuesday and Wednesday are the same"},{"id":"b","text":"Monday is the lowest"},{"id":"c","text":"The total is 20"},{"id":"d","text":"Thursday is the lowest"}]'::jsonb, '["a","c","d"]'::jsonb, 'Tuesday and Wednesday are both 7, Thursday (2) is the lowest, and 4 + 7 + 7 + 2 = 20.', '{"kind":"column_graph","title":"Rainy days","columns":[{"label":"Mon","value":4},{"label":"Tue","value":7},{"label":"Wed","value":7},{"label":"Thu","value":2}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060201', '51000000-0000-0000-0000-000000030602', 'very_easy', 1, 'How likely is it that the sun will rise tomorrow?', 'multiple_choice', '[{"id":"a","text":"certain"},{"id":"b","text":"impossible"},{"id":"c","text":"unlikely"}]'::jsonb, '"a"'::jsonb, 'The sun rises every day, so it is certain.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060202', '51000000-0000-0000-0000-000000030602', 'very_easy', 1, 'How likely is it that a cat will drive a bus to school?', 'multiple_choice', '[{"id":"a","text":"certain"},{"id":"b","text":"likely"},{"id":"c","text":"impossible"}]'::jsonb, '"c"'::jsonb, 'Cats can''t drive, so it is impossible.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060203', '51000000-0000-0000-0000-000000030602', 'very_easy', 1, 'When you flip a coin, heads and tails are equally likely.', 'true_false', NULL, '"true"'::jsonb, 'A coin has two sides and each has the same chance.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060204', '51000000-0000-0000-0000-000000030602', 'easy', 1, 'You pick one counter from this bag without looking. Which colour are you more likely to get?', 'multiple_choice', '[{"id":"a","text":"red"},{"id":"b","text":"blue"},{"id":"c","text":"they are equally likely"}]'::jsonb, '"a"'::jsonb, 'There are many more red counters than blue.', '{"kind":"bag","counters":[{"colour":"red","count":9},{"colour":"blue","count":1}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060205', '51000000-0000-0000-0000-000000030602', 'easy', 1, 'On a normal dice numbered 1 to 6, how likely is rolling a 7?', 'multiple_choice', '[{"id":"a","text":"certain"},{"id":"b","text":"likely"},{"id":"c","text":"impossible"},{"id":"d","text":"unlikely"}]'::jsonb, '"c"'::jsonb, 'There is no 7 on the dice, so it is impossible.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060206', '51000000-0000-0000-0000-000000030602', 'easy', 1, 'How many different numbers can you roll on a normal six-sided dice?', 'short_answer', NULL, '"6"'::jsonb, 'The faces show 1, 2, 3, 4, 5 and 6.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060207', '51000000-0000-0000-0000-000000030602', 'medium', 1, 'On this spinner, landing on yellow is…', 'multiple_choice', '[{"id":"a","text":"likely"},{"id":"b","text":"unlikely"},{"id":"c","text":"certain"},{"id":"d","text":"impossible"}]'::jsonb, '"b"'::jsonb, 'Only 1 part out of 4 is yellow, so it could happen but probably won''t.', '{"kind":"spinner","sections":["green","yellow","green","green"]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060208', '51000000-0000-0000-0000-000000030602', 'medium', 1, 'You pick one counter from this bag without looking. Put the colours in order from least likely to most likely.', 'ordering', '[{"id":"a","text":"red"},{"id":"b","text":"blue"},{"id":"c","text":"green"}]'::jsonb, '["a","b","c"]'::jsonb, 'Fewer marbles means less likely: red (1), blue (3), green (6).', '{"kind":"bag","counters":[{"colour":"red","count":1},{"colour":"blue","count":3},{"colour":"green","count":6}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060209', '51000000-0000-0000-0000-000000030602', 'medium', 1, 'On a normal dice, rolling an even number is as likely as rolling an odd number.', 'true_false', NULL, '"true"'::jsonb, 'There are 3 even numbers (2, 4, 6) and 3 odd numbers (1, 3, 5).', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060210', '51000000-0000-0000-0000-000000030602', 'hard', 1, 'Which of these is unlikely but possible when you roll a normal dice?', 'multiple_choice', '[{"id":"a","text":"Rolling a 6"},{"id":"b","text":"Rolling a number less than 7"},{"id":"c","text":"Rolling a 0"},{"id":"d","text":"Rolling a number from 1 to 5"}]'::jsonb, '"a"'::jsonb, 'A 6 is only 1 of the 6 faces, so it is unlikely but possible. Less than 7 is certain, 0 is impossible, and 1 to 5 is likely.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060211', '51000000-0000-0000-0000-000000030602', 'hard', 1, 'You pick one counter from this bag. Which of these are true? Choose all that are right.', 'multi_select', '[{"id":"a","text":"Red and yellow are equally likely"},{"id":"b","text":"Picking green is impossible"},{"id":"c","text":"Picking red is certain"},{"id":"d","text":"Picking red or yellow is certain"}]'::jsonb, '["a","b","d"]'::jsonb, 'There are equal numbers of red and yellow, no green, and every counter is red or yellow. Red alone is not certain.', '{"kind":"bag","counters":[{"colour":"red","count":5},{"colour":"yellow","count":5}]}'::jsonb, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060212', '51000000-0000-0000-0000-000000030602', 'hard', 1, 'Lily flipped a coin 20 times and got 11 heads. How many tails did she get?', 'short_answer', NULL, '"9"'::jsonb, 'Every flip is heads or tails, so 20 − 11 = 9 tails.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060213', '51000000-0000-0000-0000-000000030602', 'very_hard', 1, 'A spinner landed on blue 18 times out of 20 spins. What is the best guess about the spinner?', 'multiple_choice', '[{"id":"a","text":"Most of it is blue"},{"id":"b","text":"None of it is blue"},{"id":"c","text":"Exactly half is blue"},{"id":"d","text":"Landing on blue is impossible"}]'::jsonb, '"a"'::jsonb, 'Landing on blue 18 times out of 20 suggests most of the spinner is blue.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060214', '51000000-0000-0000-0000-000000030602', 'very_hard', 1, 'Which bag gives you the best chance of picking a red counter?', 'multiple_choice', '[{"id":"a","text":"2 red, 8 blue"},{"id":"b","text":"5 red, 5 blue"},{"id":"c","text":"7 red, 3 blue"},{"id":"d","text":"1 red, 1 blue"}]'::jsonb, '"c"'::jsonb, '7 red out of 10 counters is the biggest share of red.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003060215', '51000000-0000-0000-0000-000000030602', 'very_hard', 1, 'If you flip a coin and get heads 3 times in a row, tails is more likely next time.', 'true_false', NULL, '"false"'::jsonb, 'The coin doesn''t remember. Each flip is still equally likely to be heads or tails.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030101', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'Which of these shapes have exactly 4 sides? Choose all that apply.', 'multi_select', '[{"id":"a","text":"square"},{"id":"b","text":"triangle"},{"id":"c","text":"rectangle"},{"id":"d","text":"pentagon"},{"id":"e","text":"rhombus"}]'::jsonb, '["a","c","e"]'::jsonb, 'Squares, rectangles and rhombuses all have 4 sides. A triangle has 3 and a pentagon has 5.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030102', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'How many sides does a hexagon have?', 'short_answer', NULL, '["6","six"]'::jsonb, 'A hexagon has 6 sides. Think of the cells in a beehive.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030103', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'Every square is also a rectangle.', 'true_false', NULL, '"true"'::jsonb, 'A rectangle has 4 sides and 4 right angles. A square has those too, with all sides the same length, so it''s a special rectangle.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030104', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'Which shape has 5 sides?', 'multiple_choice', '[{"id":"a","text":"hexagon"},{"id":"b","text":"octagon"},{"id":"c","text":"pentagon"},{"id":"d","text":"quadrilateral"}]'::jsonb, '"c"'::jsonb, 'A pentagon has 5 sides.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030105', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'An octagon has ___ sides.', 'fill_blank', NULL, '["8","eight"]'::jsonb, 'An octagon has 8 sides, like a stop sign.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004030106', '51000000-0000-0000-0000-000000040301', 'medium', 1, 'A triangle can have two right angles.', 'true_false', NULL, '"false"'::jsonb, 'Two right angles already make 180°, which is all the angles in a triangle added together, so there''d be nothing left for the third angle.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030301', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Put these numbers in order, from smallest to largest.', 'ordering', '[{"id":"a","text":"0.05"},{"id":"b","text":"0.5"},{"id":"c","text":"0.505"},{"id":"d","text":"0.55"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Compare the tenths first, then the hundredths, then the thousandths: 0.05, 0.5, 0.505, 0.55.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030302', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Which number is the largest?', 'multiple_choice', '[{"id":"a","text":"0.68"},{"id":"b","text":"0.7"},{"id":"c","text":"0.699"},{"id":"d","text":"0.07"}]'::jsonb, '"b"'::jsonb, '0.7 has 7 tenths. The others have fewer tenths, so 0.7 is the largest.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030303', '51000000-0000-0000-0000-000000050303', 'medium', 1, '0.4 is the same as 0.40.', 'true_false', NULL, '"true"'::jsonb, '0.40 is 4 tenths and 0 hundredths, which is the same as 0.4.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030304', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'Which of these numbers are greater than 0.5? Choose all that apply.', 'multi_select', '[{"id":"a","text":"0.51"},{"id":"b","text":"0.499"},{"id":"c","text":"0.6"},{"id":"d","text":"0.05"},{"id":"e","text":"0.500"}]'::jsonb, '["a","c"]'::jsonb, '0.51 and 0.6 are greater than 0.5. 0.500 is equal to 0.5, not greater.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005030305', '51000000-0000-0000-0000-000000050303', 'medium', 1, 'What number is exactly halfway between 0.2 and 0.3?', 'short_answer', NULL, '"0.25"'::jsonb, '0.2 is 0.20 and 0.3 is 0.30. Halfway between 20 hundredths and 30 hundredths is 25 hundredths, or 0.25.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030101', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'What do we call an angle of exactly 90°?', 'multiple_choice', '[{"id":"a","text":"an acute angle"},{"id":"b","text":"a right angle"},{"id":"c","text":"an obtuse angle"},{"id":"d","text":"a straight angle"}]'::jsonb, '"b"'::jsonb, 'An angle of exactly 90° is a right angle, like the corner of a book.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030102', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Angles on a straight line add up to how many degrees?', 'short_answer', NULL, '"180"'::jsonb, 'Angles on a straight line add up to 180°.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030103', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Two angles together make a straight line. One is 65°. How many degrees is the other one?', 'short_answer', NULL, '"115"'::jsonb, 'Angles on a straight line add up to 180°, so the other angle is 180 − 65 = 115°.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030104', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Which of these angles are obtuse? Choose all that apply.', 'multi_select', '[{"id":"a","text":"45°"},{"id":"b","text":"120°"},{"id":"c","text":"90°"},{"id":"d","text":"170°"},{"id":"e","text":"200°"}]'::jsonb, '["b","d"]'::jsonb, 'Obtuse angles are between 90° and 180°, so 120° and 170° are obtuse. 200° is a reflex angle.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030105', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'The angles inside any triangle add up to 180°.', 'true_false', NULL, '"true"'::jsonb, 'The three angles inside every triangle add up to 180°.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006030106', '51000000-0000-0000-0000-000000060301', 'medium', 1, 'Angles around a point add up to how many degrees?', 'short_answer', NULL, '"360"'::jsonb, 'A full turn is 360°, so angles around a point add up to 360°.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140101', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Which sentence is written correctly?', 'multiple_choice', '[{"id":"a","text":"my dog is called rex."},{"id":"b","text":"My dog is called Rex."},{"id":"c","text":"My dog is called rex"},{"id":"d","text":"my Dog is called Rex."}]'::jsonb, '"b"'::jsonb, 'A sentence starts with a capital letter and ends with a full stop. Rex is a name, so it needs a capital letter too.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140102', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Which of these words should always start with a capital letter? Choose all that apply.', 'multi_select', '[{"id":"a","text":"sydney"},{"id":"b","text":"monday"},{"id":"c","text":"banana"},{"id":"d","text":"emma"},{"id":"e","text":"school"}]'::jsonb, '["a","b","d"]'::jsonb, 'Names of places (Sydney), days (Monday) and people (Emma) always start with a capital letter.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140103', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'A sentence can end with a full stop, a question mark or an exclamation mark.', 'true_false', NULL, '"true"'::jsonb, 'All three can end a sentence. A question mark ends a question and an exclamation mark shows strong feeling.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140104', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Type the punctuation mark that ends this question: Where are you going___', 'fill_blank', NULL, '"?"'::jsonb, 'It''s a question, so it ends with a question mark: Where are you going?', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000003140105', '51000000-0000-0000-0000-000000031401', 'medium', 1, 'Which word in this sentence should start with a capital letter? ''On saturday we went to the beach.''', 'multiple_choice', '[{"id":"a","text":"we"},{"id":"b","text":"saturday"},{"id":"c","text":"went"},{"id":"d","text":"beach"}]'::jsonb, '"b"'::jsonb, 'Days of the week always start with a capital letter: Saturday.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120101', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Which of these words are nouns? Choose all that apply.', 'multi_select', '[{"id":"a","text":"table"},{"id":"b","text":"quickly"},{"id":"c","text":"dog"},{"id":"d","text":"jump"},{"id":"e","text":"city"}]'::jsonb, '["a","c","e"]'::jsonb, 'Nouns name people, places and things: table, dog and city. ''Quickly'' is an adverb and ''jump'' is a verb.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120102', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Which word is the verb in this sentence? ''The children laughed at the funny clown.''', 'multiple_choice', '[{"id":"a","text":"children"},{"id":"b","text":"laughed"},{"id":"c","text":"funny"},{"id":"d","text":"clown"}]'::jsonb, '"b"'::jsonb, 'A verb is a doing word. ''Laughed'' is what the children did.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120103', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Which word is an adjective in this sentence? ''A tiny bird sang outside.''', 'multiple_choice', '[{"id":"a","text":"tiny"},{"id":"b","text":"bird"},{"id":"c","text":"sang"},{"id":"d","text":"outside"}]'::jsonb, '"a"'::jsonb, 'An adjective describes a noun. ''Tiny'' describes the bird.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120104', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'In the sentence ''Mia runs fast'', the word ''runs'' is a verb.', 'true_false', NULL, '"true"'::jsonb, '''Runs'' is what Mia does, so it''s a verb.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120105', '51000000-0000-0000-0000-000000041201', 'medium', 1, 'Write the past tense of ''go'' to finish the sentence: Yesterday I ___ to the park.', 'fill_blank', NULL, '"went"'::jsonb, 'The past tense of ''go'' is ''went'': Yesterday I went to the park.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120201', '51000000-0000-0000-0000-000000041202', 'medium', 1, 'Put the words in order to make a sentence.', 'ordering', '[{"id":"a","text":"The"},{"id":"b","text":"dog"},{"id":"c","text":"barked"},{"id":"d","text":"loudly."}]'::jsonb, '["a","b","c","d"]'::jsonb, 'The capital letter shows the first word and the full stop shows the last: The dog barked loudly.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120202', '51000000-0000-0000-0000-000000041202', 'medium', 1, 'Put these events in the order they happened.', 'ordering', '[{"id":"a","text":"Sam woke up and got dressed."},{"id":"b","text":"Sam ate breakfast."},{"id":"c","text":"Sam walked to school."},{"id":"d","text":"The school bell rang."}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Sam got up, had breakfast, walked to school, and then the bell rang.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000004120203', '51000000-0000-0000-0000-000000041202', 'medium', 1, 'Put these words in alphabetical order.', 'ordering', '[{"id":"a","text":"emu"},{"id":"b","text":"kangaroo"},{"id":"c","text":"koala"},{"id":"d","text":"wombat"}]'::jsonb, '["a","b","c","d"]'::jsonb, 'Look at the first letters: e, k, k, w. ''Kangaroo'' and ''koala'' both start with k, so look at the second letters: a comes before o.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140101', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'One dog has a bone. Which is correct?', 'multiple_choice', '[{"id":"a","text":"the dogs bone"},{"id":"b","text":"the dog''s bone"},{"id":"c","text":"the dogs'' bone"},{"id":"d","text":"the dog,s bone"}]'::jsonb, '"b"'::jsonb, 'To show something belongs to one owner, add ''s: the dog''s bone.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140102', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'Write the short form (contraction) of ''do not'': ___', 'fill_blank', NULL, '"don''t"'::jsonb, '''Do not'' becomes ''don''t''. The apostrophe takes the place of the missing o.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140103', '51000000-0000-0000-0000-000000051401', 'medium', 1, '''Its'' with no apostrophe means ''belonging to it''.', 'true_false', NULL, '"true"'::jsonb, '''Its'' means belonging to it (the dog wagged its tail). ''It''s'' is short for ''it is'' or ''it has''.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140104', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'Which sentences use apostrophes correctly? Choose all that apply.', 'multi_select', '[{"id":"a","text":"I can''t come."},{"id":"b","text":"The cat''s tail is long."},{"id":"c","text":"I like apple''s."},{"id":"d","text":"We''re late!"},{"id":"e","text":"The boy''s are playing."}]'::jsonb, '["a","b","d"]'::jsonb, '''Can''t'' and ''we''re'' are contractions, and ''cat''s'' shows the tail belongs to the cat. Plurals like ''apples'' and ''boys'' don''t need an apostrophe.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000005140105', '51000000-0000-0000-0000-000000051401', 'medium', 1, 'Write the short form (contraction) of ''they are'': ___', 'fill_blank', NULL, '"they''re"'::jsonb, '''They are'' becomes ''they''re''. The apostrophe takes the place of the missing a.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120101', '51000000-0000-0000-0000-000000061201', 'medium', 1, 'Which sentence uses a simile?', 'multiple_choice', '[{"id":"a","text":"The wind howled all night."},{"id":"b","text":"She was as quiet as a mouse."},{"id":"c","text":"The classroom was a zoo."},{"id":"d","text":"Buzz went the bee."}]'::jsonb, '"b"'::jsonb, 'A simile compares two things using ''like'' or ''as'': as quiet as a mouse.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120102', '51000000-0000-0000-0000-000000061201', 'medium', 1, '''The classroom was a zoo.'' What kind of figurative language is this?', 'multiple_choice', '[{"id":"a","text":"simile"},{"id":"b","text":"metaphor"},{"id":"c","text":"onomatopoeia"},{"id":"d","text":"alliteration"}]'::jsonb, '"b"'::jsonb, 'It''s a metaphor: it says the classroom was a zoo, without ''like'' or ''as''.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120103', '51000000-0000-0000-0000-000000061201', 'medium', 1, 'A simile compares two things using ''like'' or ''as''.', 'true_false', NULL, '"true"'::jsonb, 'That''s what makes it a simile, for example ''as brave as a lion''.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120104', '51000000-0000-0000-0000-000000061201', 'medium', 1, 'Which of these words are onomatopoeia? Choose all that apply.', 'multi_select', '[{"id":"a","text":"buzz"},{"id":"b","text":"sizzle"},{"id":"c","text":"happy"},{"id":"d","text":"crash"},{"id":"e","text":"slowly"}]'::jsonb, '["a","b","d"]'::jsonb, 'Onomatopoeia words sound like what they describe: buzz, sizzle and crash.', NULL, '90000000-0000-0000-0000-000000000001'),
  ('61000000-0000-0000-0000-000006120105', '51000000-0000-0000-0000-000000061201', 'medium', 1, '''The sun smiled down on us.'' What kind of figurative language is this?', 'multiple_choice', '[{"id":"a","text":"personification"},{"id":"b","text":"simile"},{"id":"c","text":"onomatopoeia"},{"id":"d","text":"alliteration"}]'::jsonb, '"a"'::jsonb, 'The sun can''t really smile. Giving human actions to things that aren''t human is personification.', NULL, '90000000-0000-0000-0000-000000000001')
